АдресAPI = Объект.АдресGitAPI;
Репозиторий = Объект.РепозиторийGit;
Ветка = Объект.ВеткаGit;
Токен = Объект.ТокенGit;
КаталогЗнаний = Объект.КаталогБазыЗнанийGit;

СтруктураURL = ОбщегоНазначенияКлиентСервер.СтруктураURI(АдресAPI);
Сервер = СтруктураURL.Хост;
Порт = ?(ЗначениеЗаполнено(СтруктураURL.Порт), СтруктураURL.Порт, Неопределено);
Защищённое = (НРег(СтруктураURL.Схема) = "https");

Соединение = Новый HTTPСоединение(Сервер, Порт, , , , , ?(Защищённое, Новый ЗащищенноеСоединениеOpenSSL(), Неопределено));

ПутьЗапроса = СтрШаблон("/repos/%1/git/trees/%2?recursive=1", Репозиторий, Ветка);
Заголовки = Новый Соответствие;
Заголовки.Вставить("Authorization", "Bearer " + Токен);
Запрос = Новый HTTPЗапрос(ПутьЗапроса, Заголовки);

Ответ = Соединение.Получить(Запрос);
Если Ответ.КодСостояния = 200 Тогда
	ТелоОтвета = Ответ.ПолучитьТелоКакСтроку();
	ЧтениеJSON = Новый ЧтениеJSON;
	ЧтениеJSON.УстановитьСтроку(ТелоОтвета);
	Данные = ПрочитатьJSON(ЧтениеJSON);
	ЧтениеJSON.Закрыть();

	КоличествоФайлов = 0;
	Если Данные.Свойство("tree") Тогда
		Для Каждого Элемент Из Данные.tree Цикл
			Если Элемент.type = "blob" И СтрНачинаетсяС(Элемент.path, КаталогЗнаний) Тогда
				КоличествоФайлов = КоличествоФайлов + 1;
			КонецЕсли;
		КонецЦикла;
	КонецЕсли;

	Результат = СтрШаблон("В каталоге знаний '%1' найдено файлов: %2", КаталогЗнаний, КоличествоФайлов);
Иначе
	Результат = СтрШаблон("Ошибка запроса к Git API. Код: %1. Тело: %2", Ответ.КодСостояния, Ответ.ПолучитьТелоКакСтроку());
КонецЕсли;
